function searchNutrition(q, limit) {
  if (!q) return NUTRITION.slice(0, limit || 200);
  var kw = String(q).trim().toLowerCase();
  var res = NUTRITION.filter(function (x) {
    return (x.name && x.name.toLowerCase().indexOf(kw) > -1) ||
           (x.commonName && x.commonName.toLowerCase().indexOf(kw) > -1);
  });
  return limit ? res.slice(0, limit) : res;
}

function getById(id) {
  return NUTRITION.find(function (x) { return x.id === id; }) || null;
}

module.exports = { NUTRITION: NUTRITION, searchNutrition: searchNutrition, getById: getById, count: NUTRITION.length };